class Solution:
    def shortestCut(self, s: str) -> int:
        n, best = len(s), len(s)
        for i in range(n + 1):
            for j in range(i, n + 1):
                if j - i < best:
                    kept = s[:i] + s[j:]
                    if kept == kept[::-1]:
                        best = j - i
        return best

