class Solution {
    public int shortestCut(String s) {
        int n = s.length(), best = n;
        for (int i = 0; i <= n; i++)
            for (int j = i; j <= n; j++) {
                if (j - i >= best) continue;
                int m = n - (j - i), a = 0, b = m - 1;
                boolean ok = true;
                while (a < b && ok) {
                    char x = s.charAt(a < i ? a : a + j - i), y = s.charAt(b < i ? b : b + j - i);
                    if (x != y) ok = false;
                    a++; b--;
                }
                if (ok) best = j - i;
            }
        return best;
    }
}

