class Solution:
    def shortestCut(self, s: str) -> int:
        n, l = len(s), 0
        while l < n - 1 - l and s[l] == s[n - 1 - l]:
            l += 1
        mid = s[l:n - l]
        def pal(t):
            return t == t[::-1]
        pre = next(k for k in range(len(mid), -1, -1) if pal(mid[:k]))
        suf = next(k for k in range(len(mid), -1, -1) if pal(mid[len(mid) - k:]))
        return len(mid) - max(pre, suf)

