class Solution {
    private boolean pal(String s, int i, int j) {
        while (i < j) if (s.charAt(i++) != s.charAt(j--)) return false;
        return true;
    }

    public int shortestCut(String s) {
        int n = s.length(), l = 0;
        while (l < n - 1 - l && s.charAt(l) == s.charAt(n - 1 - l)) l++;
        int lo = l, hi = n - 1 - l, m = hi - lo + 1;
        int pre = 0, suf = 0;
        for (int k = m; k > 0 && pre == 0; k--) if (pal(s, lo, lo + k - 1)) pre = k;
        for (int k = m; k > 0 && suf == 0; k--) if (pal(s, hi - k + 1, hi)) suf = k;
        return m - Math.max(pre, suf);
    }
}

