class Solution {
    private int palPrefix(String t) {
        String u = t + "#" + new StringBuilder(t).reverse();
        int[] pi = new int[u.length()];
        for (int i = 1; i < u.length(); i++) {
            int k = pi[i - 1];
            while (k > 0 && u.charAt(i) != u.charAt(k)) k = pi[k - 1];
            if (u.charAt(i) == u.charAt(k)) k++;
            pi[i] = k;
        }
        return pi[u.length() - 1];
    }

    public int shortestCut(String s) {
        int n = s.length(), l = 0;
        while (l < n - 1 - l && s.charAt(l) == s.charAt(n - 1 - l)) l++;
        String mid = s.substring(l, n - l);
        if (mid.length() <= 1) return 0;
        return mid.length() - Math.max(palPrefix(mid), palPrefix(new StringBuilder(mid).reverse().toString()));
    }
}

