class Solution {
    static int palPrefix(const string& t) {
        string u = t + "#" + string(t.rbegin(), t.rend());
        vector<int> pi(u.size(), 0);
        for (size_t i = 1; i < u.size(); i++) {
            int k = pi[i - 1];
            while (k > 0 && u[i] != u[k]) k = pi[k - 1];
            if (u[i] == u[k]) k++;
            pi[i] = k;
        }
        return pi.back();
    }

public:
    int shortestCut(string& s) {
        int n = s.size(), l = 0;
        while (l < n - 1 - l && s[l] == s[n - 1 - l]) l++;
        string mid = s.substr(l, n - 2 * l);
        if (mid.size() <= 1) return 0;
        return mid.size() - max(palPrefix(mid), palPrefix(string(mid.rbegin(), mid.rend())));
    }
};

