static int pal_prefix(const char* t, int m, int reversed) {
    int len = 2 * m + 1;
    char* u = malloc(len);
    for (int i = 0; i < m; i++) {
        char c = reversed ? t[m - 1 - i] : t[i];
        u[i] = c;
        u[len - 1 - i] = c;
    }
    u[m] = '#';
    int* pi = calloc(len, sizeof(int));
    for (int i = 1; i < len; i++) {
        int k = pi[i - 1];
        while (k > 0 && u[i] != u[k]) k = pi[k - 1];
        if (u[i] == u[k]) k++;
        pi[i] = k;
    }
    int answer = pi[len - 1];
    free(u); free(pi);
    return answer;
}

int shortestCut(char* s) {
    int n = strlen(s), l = 0;
    while (l < n - 1 - l && s[l] == s[n - 1 - l]) l++;
    int m = n - 2 * l;
    if (m <= 1) return 0;
    int a = pal_prefix(s + l, m, 0), b = pal_prefix(s + l, m, 1);
    return m - (a > b ? a : b);
}
